style.css:
@-moz-document domain("roblox.com") {
body, html {
        background: url("https://i.imgur.com/vtPzMgv.jpeg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Optional: Make content backgrounds slightly transparent */
    .content, .container-main, .game-main-content, .game-home-page, .game-card-container,
    .section-content, .container-header, .game-detail-page {
        background-color: rgba(0, 0, 0, 0.7) !important;
        color: white !important;
    }

    /* Optional: Adjust text color sitewide */
    * {
        color: #ffffff !important;
    }

    /* Optional: Hide annoying elements (ads, etc.) */
    .ad-container, .ads-container, .sponsorship {
        display: none !important;
    }

    /* Scrollbar styling */
    ::-webkit-scrollbar {
        width: 10px;
    }

    ::-webkit-scrollbar-track {
        background: #1e1e1e;
    }

    ::-webkit-scrollbar-thumb {
        background: #444;
        border-radius: 10px;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #888;
    }
}
